import{_ as t,o as s,c as e,a4 as i}from"./chunks/framework.vNSRaLQv.js";const k=JSON.parse('{"title":"fnOS 内核 Bug 导致 k3s 容器问题分析报告","description":"","frontmatter":{"title":"fnOS 内核 Bug 导致 k3s 容器问题分析报告","date":"2026-09-01T00:00:00.000Z"},"headers":[],"relativePath":"posts/fnos-k3s-container-issues.md","filePath":"posts/fnos-k3s-container-issues.md"}'),n={name:"posts/fnos-k3s-container-issues.md"};function r(o,a,d,l,h,c){return s(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="fnos-内核-bug-导致-k3s-容器问题分析报告" tabindex="-1">fnOS 内核 Bug 导致 k3s 容器问题分析报告 <a class="header-anchor" href="#fnos-内核-bug-导致-k3s-容器问题分析报告" aria-label="Permalink to &quot;fnOS 内核 Bug 导致 k3s 容器问题分析报告&quot;">​</a></h1><h2 id="日期" tabindex="-1">日期 <a class="header-anchor" href="#日期" aria-label="Permalink to &quot;日期&quot;">​</a></h2><p>2026-09-01</p><h2 id="环境" tabindex="-1">环境 <a class="header-anchor" href="#环境" aria-label="Permalink to &quot;环境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>节点</th><th>IP</th><th>内核</th><th>k3s</th><th>containerd</th></tr></thead><tbody><tr><td>fnos</td><td>192.168.31.182</td><td>6.18.18.c952-<strong>trim</strong> (fnOS 自定义)</td><td>v1.36.4+k3s1</td><td>2.3.4-k3s1.36</td></tr><tr><td>laptop</td><td>192.168.31.204</td><td>6.12.95+deb13-amd64 (标准 Debian)</td><td>v1.36.4+k3s1</td><td>2.3.4-k3s1.36</td></tr></tbody></table><p><strong>两个节点 containerd 版本完全一致</strong>，问题出在 fnOS 自定义内核。</p><hr><h2 id="bug-1-containerd-sandbox-resolv-conf-权限被锁为-0700" tabindex="-1">Bug 1: containerd sandbox resolv.conf 权限被锁为 0700 <a class="header-anchor" href="#bug-1-containerd-sandbox-resolv-conf-权限被锁为-0700" aria-label="Permalink to &quot;Bug 1: containerd sandbox resolv.conf 权限被锁为 0700&quot;">​</a></h2><h3 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to &quot;现象&quot;">​</a></h3><p>k3s 在 fnOS 上创建的 containerd sandbox <code>resolv.conf</code> 权限为 <code>0700</code>（仅 root 可读），标准 Debian 上正常为 <code>0644</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span># fnOS 节点</span></span>
<span class="line"><span>-rwx------ 1 root root 110 .../sandboxes/&lt;id&gt;/resolv.conf</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 标准 Debian 节点</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 107 .../sandboxes/&lt;id&gt;/resolv.conf</span></span></code></pre></div><h3 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h3><ul><li>所有以非 root 用户运行的 Go 服务（<code>CGO_ENABLED=0</code>）DNS 解析失败</li><li>Go 内置 DNS 解析器读 <code>/etc/resolv.conf</code> → Permission denied → 回退到 <code>[::1]:53</code></li><li>数据库连接失败 → 服务 CrashLoopBackOff</li><li><strong>注意：admin 是 nginx 静态前端，不连数据库，所以不崩溃</strong></li></ul><h3 id="排除过程" tabindex="-1">排除过程 <a class="header-anchor" href="#排除过程" aria-label="Permalink to &quot;排除过程&quot;">​</a></h3><ol><li>❌ kubelet umask 设置 → 设为 0022 后无效</li><li>❌ containerd 1.7.29 CVE-2024-25621 → 两个节点都是 containerd 2.3.4，排除</li><li>❌ containerd CRI 源码 → 源码中 resolv.conf 用 0644 创建，排除代码问题</li><li>❌ k3s umask wrapper → 改 umask 后无效，containerd 显式 chmod</li><li>✅ <strong>根因确认：fnOS 自定义内核修改了文件创建后的权限位</strong></li></ol><h3 id="临时修复" tabindex="-1">临时修复 <a class="header-anchor" href="#临时修复" aria-label="Permalink to &quot;临时修复&quot;">​</a></h3><p>定时任务每 5 秒 chmod 644 所有 sandbox resolv.conf：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># /usr/local/bin/fix-vol1-perms.sh 中新增</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">find</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /var/lib/rancher/k3s/agent/containerd/io.containerd.grpc.v1.cri/sandboxes</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> \\</span></span>
<span class="line"><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;">  -name</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;"> &quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">resolv.conf</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -perm</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 0700</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -exec</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> chmod</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 644</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> {}</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> \\;</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> 2&gt;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">/dev/null</span></span></code></pre></div><hr><h2 id="bug-2-redis-容器-createcontainererror-system-trim-acl-xattr" tabindex="-1">Bug 2: redis 容器 CreateContainerError（system.trim_acl xattr） <a class="header-anchor" href="#bug-2-redis-容器-createcontainererror-system-trim-acl-xattr" aria-label="Permalink to &quot;Bug 2: redis 容器 CreateContainerError（system.trim_acl xattr）&quot;">​</a></h2><h3 id="现象-1" tabindex="-1">现象 <a class="header-anchor" href="#现象-1" aria-label="Permalink to &quot;现象&quot;">​</a></h3><p>redis pod 无法启动：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Error: failed to create containerd container: taking runtime copy of volume:</span></span>
<span class="line"><span>failed to copy xattrs: failed to get xattr &quot;system.trim_acl&quot;</span></span>
<span class="line"><span>on /tmp/ctd-volume*/data: operation not supported</span></span></code></pre></div><h3 id="分析" tabindex="-1">分析 <a class="header-anchor" href="#分析" aria-label="Permalink to &quot;分析&quot;">​</a></h3><ul><li>根分区 <code>/dev/sda2</code>（ext4）<strong>没有</strong> <code>trimacl</code> 挂载选项</li><li><code>/vol1</code> 分区（ext4）<strong>有</strong> <code>trimacl</code> 挂载选项</li><li>containerd 使用 <code>/tmp</code>（根分区）作为临时 volume 存储</li><li>创建容器时复制 xattr，内核在不支持 trimacl 的分区上尝试操作 <code>system.trim_acl</code> → 失败</li></ul><h3 id="临时修复-1" tabindex="-1">临时修复 <a class="header-anchor" href="#临时修复-1" aria-label="Permalink to &quot;临时修复&quot;">​</a></h3><p>等待飞牛内核修复，或尝试：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">mount</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -o</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> remount,trimacl</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">   # 给根分区加上 trimacl 支持</span></span></code></pre></div><hr><h2 id="bug-3-vol1-权限被内核置-000-已知问题" tabindex="-1">Bug 3: /vol1 权限被内核置 000（已知问题） <a class="header-anchor" href="#bug-3-vol1-权限被内核置-000-已知问题" aria-label="Permalink to &quot;Bug 3: /vol1 权限被内核置 000（已知问题）&quot;">​</a></h2><h3 id="现象-2" tabindex="-1">现象 <a class="header-anchor" href="#现象-2" aria-label="Permalink to &quot;现象&quot;">​</a></h3><p>容器操作（k3s 调度）触发内核 umount 冲突检测后，<code>/vol1</code> 权限被锁为 <code>000</code>，k3s 节点 NotReady。</p><h3 id="临时修复-2" tabindex="-1">临时修复 <a class="header-anchor" href="#临时修复-2" aria-label="Permalink to &quot;临时修复&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">chmod</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 644</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /vol1</span></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 或通过 systemd timer 持续修复</span></span></code></pre></div><hr><h2 id="根因总结" tabindex="-1">根因总结 <a class="header-anchor" href="#根因总结" aria-label="Permalink to &quot;根因总结&quot;">​</a></h2><p>fnOS 自定义内核 <code>6.18.18.c952-trim</code> 的 ext4 补丁存在以下问题：</p><ol><li><strong>文件权限锁死</strong>：容器操作触发 umount 冲突检测后，内核错误地修改新建文件的权限位（resolv.conf → 0700，/vol1 → 000）</li><li><strong>trimacl xattr 不完整</strong>：内核的 trimacl 补丁在不支持 trimacl 的文件系统上仍尝试操作 <code>system.trim_acl</code> xattr</li></ol><p>对比：标准 Debian 内核（laptop 节点）无此问题，两个节点 containerd 版本完全一致。</p><hr><h2 id="提交的-issue" tabindex="-1">提交的 Issue <a class="header-anchor" href="#提交的-issue" aria-label="Permalink to &quot;提交的 Issue&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>Issue</th><th>状态</th></tr></thead><tbody><tr><td>k3s</td><td><a href="https://github.com/k3s-io/k3s/issues/14563" target="_blank" rel="noreferrer">#14563</a></td><td>open</td></tr><tr><td>containerd</td><td><a href="https://github.com/containerd/containerd/issues/14078" target="_blank" rel="noreferrer">#14078</a></td><td><strong>已关闭</strong>（确认不是 containerd 问题）</td></tr><tr><td>fnOS</td><td><a href="https://github.com/ophub/fnnas/issues/649" target="_blank" rel="noreferrer">ophub/fnnas#649</a></td><td>open</td></tr><tr><td>飞牛论坛</td><td><a href="https://club.fnnas.com/forum.php?mod=viewthread&amp;tid=42361" target="_blank" rel="noreferrer">club.fnnas.com #42361</a></td><td>open</td></tr></tbody></table><hr><h2 id="当前状态-2026-09-01" tabindex="-1">当前状态（2026-09-01） <a class="header-anchor" href="#当前状态-2026-09-01" aria-label="Permalink to &quot;当前状态（2026-09-01）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>服务</th><th>状态</th></tr></thead><tbody><tr><td>k3s 两个节点</td><td>✅ Ready</td></tr><tr><td>所有 Go 后端服务</td><td>✅ Running（initContainer 兜底 resolv.conf）</td></tr><tr><td>redis</td><td>❌ CreateContainerError（xattr 问题）</td></tr><tr><td>飞牛 nginx 管理面板</td><td>✅ 正常</td></tr><tr><td>resolv.conf 修复</td><td>✅ timer 持续修复</td></tr></tbody></table><h2 id="待办" tabindex="-1">待办 <a class="header-anchor" href="#待办" aria-label="Permalink to &quot;待办&quot;">​</a></h2><ol><li>等待飞牛发布修复内核</li><li>修复 redis xattr 问题（需要 <code>mount -o remount,trimacl /</code> 或等内核修复）</li><li>内核修复后移除 initContainer workaround 和 timer</li></ol>`,47)])])}const b=t(n,[["render",r]]);export{k as __pageData,b as default};
